9	package org.elasticsearch.geometry.utils;
10	
11	import org.elasticsearch.geometry.Point;
12	import org.elasticsearch.geometry.Rectangle;
13	
14	import java.util.ArrayList;
15	import java.util.Collection;
16	
17	/**
18	 * Utilities for converting to/from the GeoHash standard
19	 *
20	 * The geohash long format is represented as lon/lat (x/y) interleaved with the 4 least significant bits
21	 * representing the level (1-12) [xyxy...xyxyllll]
22	 *
23	 * This differs from a morton encoded value which interleaves lat/lon (y/x).
24	 *
25	 * NOTE: this will replace {@code org.elasticsearch.common.geo.GeoHashUtils}
26	 */
27	public class Geohash {
28	    private static final char[] BASE_32 = {
29	        '0',
30	        '1',
31	        '2',
32	        '3',
33	        '4',
34	        '5',
35	        '6',
36	        '7',
37	        '8',
38	        '9',
39	        'b',
40	        'c',
41	        'd',
42	        'e',
43	        'f',
44	        'g',
45	        'h',
46	        'j',
47	        'k',
48	        'm',
49	        'n',
50	        'p',
51	        'q',
52	        'r',
53	        's',
54	        't',
55	        'u',
56	        'v',
57	        'w',
58	        'x',
59	        'y',
60	        'z' };
61	
62	    private static final String BASE_32_STRING = new String(BASE_32);
63	    /** maximum precision for geohash strings */
64	    public static final int PRECISION = 12;
65	    /** number of bits used for quantizing latitude and longitude values */
66	    private static final short BITS = 32;
67	    private static final double LAT_SCALE = (0x1L << (BITS - 1)) / 180.0D;
68	    private static final double LAT_DECODE = 180.0D / (0x1L << BITS);
69	    private static final double LON_SCALE = (0x1L << (BITS - 1)) / 360.0D;
70	    private static final double LON_DECODE = 360.0D / (0x1L << BITS);
71	
72	    private static final short MORTON_OFFSET = (BITS << 1) - (PRECISION * 5);
73	    /** Bit encoded representation of the latitude of north pole */
74	    private static final long MAX_LAT_BITS = (0x1L << (PRECISION * 5 / 2)) - 1;
75	
76	    // Below code is adapted from the spatial4j library (GeohashUtils.java) Apache 2.0 Licensed
77	    private static final double[] precisionToLatHeight, precisionToLonWidth;
78	    static {
79	        precisionToLatHeight = new double[PRECISION + 1];
80	        precisionToLonWidth = new double[PRECISION + 1];
81	        precisionToLatHeight[0] = 90 * 2;
82	        precisionToLonWidth[0] = 180 * 2;
83	        boolean even = false;
84	        for (int i = 1; i <= PRECISION; i++) {
85	            precisionToLatHeight[i] = precisionToLatHeight[i - 1] / (even ? 8 : 4);
86	            precisionToLonWidth[i] = precisionToLonWidth[i - 1] / (even ? 4 : 8);
87	            even = even == false;
88	        }
89	    }
90	
91	    // no instance:
92	    private Geohash() {}
93	
94	    /** Returns a {@link Point} instance from a geohash string */
95	    public static Point toPoint(final String geohash) throws IllegalArgumentException {
96	        final long hash = mortonEncode(geohash);
97	        return new Point(decodeLongitude(hash), decodeLatitude(hash));
98	    }
99	
100	    /**
101	     * Computes the bounding box coordinates from a given geohash
102	     *
103	     * @param geohash Geohash of the defined cell
104	     * @return GeoRect rectangle defining the bounding box
105	     */
106	    public static Rectangle toBoundingBox(final String geohash) {
107	        // bottom left is the coordinate
108	        Point bottomLeft = toPoint(geohash);
109	        int len = Math.min(12, geohash.length());
110	        long ghLong = longEncode(geohash, len);
111	        // shift away the level
112	        ghLong >>>= 4;
113	        // deinterleave
114	        long lon = BitUtil.deinterleave(ghLong >>> 1);
115	        long lat = BitUtil.deinterleave(ghLong);
116	        final int shift = (12 - len) * 5 + 2;
117	        if (lat < MAX_LAT_BITS) {
118	            // add 1 to lat and lon to get topRight
119	            ghLong = BitUtil.interleave((int) (lat + 1), (int) (lon + 1)) << 4 | len;
120	            final long mortonHash = BitUtil.flipFlop((ghLong >>> 4) << shift);
121	            Point topRight = new Point(decodeLongitude(mortonHash), decodeLatitude(mortonHash));
122	            return new Rectangle(bottomLeft.getX(), topRight.getX(), topRight.getY(), bottomLeft.getY());
123	        } else {
124	            // We cannot go north of north pole, so just using 90 degrees instead of calculating it using
125	            // add 1 to lon to get lon of topRight, we are going to use 90 for lat
126	            ghLong = BitUtil.interleave((int) lat, (int) (lon + 1)) << 4 | len;
127	            final long mortonHash = BitUtil.flipFlop((ghLong >>> 4) << shift);
128	            Point topRight = new Point(decodeLongitude(mortonHash), decodeLatitude(mortonHash));
129	            return new Rectangle(bottomLeft.getX(), topRight.getX(), 90D, bottomLeft.getY());
130	        }
131	    }
132	
133	    /** Array of geohashes one level below the baseGeohash. Sorted. */
134	    public static String[] getSubGeohashes(String baseGeohash) {
135	        String[] hashes = new String[BASE_32.length];
136	        for (int i = 0; i < BASE_32.length; i++) {// note: already sorted
137	            char c = BASE_32[i];
138	            hashes[i] = baseGeohash + c;
139	        }
140	        return hashes;
141	    }
142	
143	    /**
144	     * Calculate all neighbors of a given geohash cell.
145	     *
146	     * @param geohash Geohash of the defined cell
147	     * @return geohashes of all neighbor cells
148	     */
149	    public static Collection<? extends CharSequence> getNeighbors(String geohash) {
150	        return addNeighborsAtLevel(geohash, geohash.length(), new ArrayList<CharSequence>(8));
151	    }
152	
153	    /**
154	     * Add all geohashes of the cells next to a given geohash to a list.
155	     *
156	     * @param geohash   Geohash of a specified cell
157	     * @param neighbors list to add the neighbors to
158	     * @return the given list
159	     */
160	    public static final <E extends Collection<? super String>> E addNeighbors(String geohash, E neighbors) {
161	        return addNeighborsAtLevel(geohash, geohash.length(), neighbors);
162	    }
163	
164	    /**
165	     * Add all geohashes of the cells next to a given geohash to a list.
166	     *
167	     * @param geohash   Geohash of a specified cell
168	     * @param level    level of the given geohash
169	     * @param neighbors list to add the neighbors to
170	     * @return the given list
171	     */
172	    public static final <E extends Collection<? super String>> E addNeighborsAtLevel(String geohash, int level, E neighbors) {
173	        String south = getNeighbor(geohash, level, 0, -1);
174	        String north = getNeighbor(geohash, level, 0, +1);
175	        if (north != null) {
176	            neighbors.add(getNeighbor(north, level, -1, 0));
177	            neighbors.add(north);
178	            neighbors.add(getNeighbor(north, level, +1, 0));
179	        }
180	
181	        neighbors.add(getNeighbor(geohash, level, -1, 0));
182	        neighbors.add(getNeighbor(geohash, level, +1, 0));
183	
184	        if (south != null) {
185	            neighbors.add(getNeighbor(south, level, -1, 0));
186	            neighbors.add(south);
187	            neighbors.add(getNeighbor(south, level, +1, 0));
188	        }
189	
190	        return neighbors;
191	    }
192	
193	    /**
194	     * Calculate the geohash of a neighbor of a geohash
195	     *
196	     * @param geohash the geohash of a cell
197	     * @param level   level of the geohash
198	     * @param dx      delta of the first grid coordinate (must be -1, 0 or +1)
199	     * @param dy      delta of the second grid coordinate (must be -1, 0 or +1)
200	     * @return geohash of the defined cell
201	     */
202	    public static final String getNeighbor(String geohash, int level, int dx, int dy) {
203	        int cell = BASE_32_STRING.indexOf(geohash.charAt(level - 1));
204	
205	        // Decoding the Geohash bit pattern to determine grid coordinates
206	        int x0 = cell & 1;  // first bit of x
207	        int y0 = cell & 2;  // first bit of y
208	        int x1 = cell & 4;  // second bit of x
209	        int y1 = cell & 8;  // second bit of y
210	        int x2 = cell & 16; // third bit of x
211	
212	        // combine the bitpattern to grid coordinates.
213	        // note that the semantics of x and y are swapping
214	        // on each level
215	        int x = x0 + (x1 / 2) + (x2 / 4);
216	        int y = (y0 / 2) + (y1 / 4);
217	
218	        if (level == 1) {
219	            // Root cells at north (namely "bcfguvyz") or at
220	            // south (namely "0145hjnp") do not have neighbors
221	            // in north/south direction
222	            if ((dy < 0 && y == 0) || (dy > 0 && y == 3)) {
223	                return null;
224	            } else {
225	                return Character.toString(encodeBase32(x + dx, y + dy));
226	            }
227	        } else {
228	            // define grid coordinates for next level
229	            final int nx = ((level % 2) == 1) ? (x + dx) : (x + dy);
230	            final int ny = ((level % 2) == 1) ? (y + dy) : (y + dx);
231	
232	            // if the defined neighbor has the same parent a the current cell
233	            // encode the cell directly. Otherwise find the cell next to this
234	            // cell recursively. Since encoding wraps around within a cell
235	            // it can be encoded here.
236	            // xLimit and YLimit must always be respectively 7 and 3
237	            // since x and y semantics are swapping on each level.
238	            if (nx >= 0 && nx <= 7 && ny >= 0 && ny <= 3) {
239	                return geohash.substring(0, level - 1) + encodeBase32(nx, ny);
240	            } else {
241	                String neighbor = getNeighbor(geohash, level - 1, dx, dy);
242	                return (neighbor != null) ? neighbor + encodeBase32(nx, ny) : neighbor;
243	            }
244	        }
245	    }
246	
247	    /**
248	     * Encode a string geohash to the geohash based long format (lon/lat interleaved, 4 least significant bits = level)
249	     */
250	    public static final long longEncode(String hash) {
251	        return longEncode(hash, hash.length());
252	    }
253	
254	    /**
255	     * Encode lon/lat to the geohash based long format (lon/lat interleaved, 4 least significant bits = level)
256	     */
257	    public static final long longEncode(final double lon, final double lat, final int level) {
258	        // shift to appropriate level
259	        final short msf = (short) (((12 - level) * 5) + (MORTON_OFFSET - 2));
260	        return ((encodeLatLon(lat, lon) >>> msf) << 4) | level;
261	    }
262	
263	    /**
264	     * Encode to a geohash string from full resolution longitude, latitude)
265	     */
266	    public static final String stringEncode(final double lon, final double lat) {
267	        return stringEncode(lon, lat, 12);
268	    }
269	
270	    /**
271	     * Encode to a level specific geohash string from full resolution longitude, latitude
272	     */
273	    public static final String stringEncode(final double lon, final double lat, final int level) {
274	        // convert to geohashlong
275	        long interleaved = encodeLatLon(lat, lon);
276	        interleaved >>>= (((PRECISION - level) * 5) + (MORTON_OFFSET - 2));
277	        final long geohash = (interleaved << 4) | level;
278	        return stringEncode(geohash);
279	    }
280	
281	    /**
282	     * Encode to a geohash string from the geohash based long format
283	     */
284	    public static final String stringEncode(long geoHashLong) {
285	        int level = (int) geoHashLong & 15;
286	        geoHashLong >>>= 4;
287	        char[] chars = new char[level];
288	        do {
289	            chars[--level] = BASE_32[(int) (geoHashLong & 31L)];
290	            geoHashLong >>>= 5;
291	        } while (level > 0);
292	
293	        return new String(chars);
294	    }
295	
296	    /** base32 encode at the given grid coordinate */
297	    private static char encodeBase32(int x, int y) {
298	        return BASE_32[((x & 1) + ((y & 1) * 2) + ((x & 2) * 2) + ((y & 2) * 4) + ((x & 4) * 4)) % 32];
299	    }
300	
301	    /**
302	     * Encode from geohash string to the geohash based long format (lon/lat interleaved, 4 least significant bits = level)
303	     */
304	    private static long longEncode(final String hash, int length) {
305	        int level = length - 1;
306	        long b;
307	        long l = 0L;
308	        for (char c : hash.toCharArray()) {
309	            b = (long) (BASE_32_STRING.indexOf(c));
310	            l |= (b << (level-- * 5));
311	            if (level < 0) {
312	                // We cannot handle more than 12 levels
313	                break;
314	            }
315	        }
316	        return (l << 4) | length;
317	    }
318	
319	    /**
320	     * Encode to a morton long value from a given geohash string
321	     */
322	    public static long mortonEncode(final String hash) {
323	        if (hash.isEmpty()) {
324	            throw new IllegalArgumentException("empty geohash");
325	        }
326	        int level = 11;
327	        long b;
328	        long l = 0L;
329	        for (char c : hash.toCharArray()) {
330	            b = (long) (BASE_32_STRING.indexOf(c));
331	            if (b < 0) {
332	                throw new IllegalArgumentException("unsupported symbol [" + c + "] in geohash [" + hash + "]");
333	            }
334	            l |= (b << ((level-- * 5) + (MORTON_OFFSET - 2)));
335	            if (level < 0) {
336	                // We cannot handle more than 12 levels
337	                break;
338	            }
339	        }
340	        return BitUtil.flipFlop(l);
341	    }
342	
343	    /** approximate width of geohash tile for a specific precision in degrees */
344	    public static double lonWidthInDegrees(int precision) {
345	        return precisionToLonWidth[precision];
346	    }
347	
348	    /** approximate height of geohash tile for a specific precision in degrees */
349	    public static double latHeightInDegrees(int precision) {
350	        return precisionToLatHeight[precision];
351	    }
352	
353	    private static long encodeLatLon(final double lat, final double lon) {
354	        // encode lat/lon flipping the sign bit so negative ints sort before positive ints
355	        final int latEnc = encodeLatitude(lat) ^ 0x80000000;
356	        final int lonEnc = encodeLongitude(lon) ^ 0x80000000;
357	        return BitUtil.interleave(latEnc, lonEnc) >>> 2;
358	    }
359	
360	    /** encode latitude to integer */
361	    public static int encodeLatitude(double latitude) {
362	        // the maximum possible value cannot be encoded without overflow
363	        if (latitude == 90.0D) {
364	            latitude = Math.nextDown(latitude);
365	        }
366	        return (int) Math.floor(latitude / LAT_DECODE);
367	    }
368	
369	    /** encode longitude to integer */
370	    public static int encodeLongitude(double longitude) {
371	        // the maximum possible value cannot be encoded without overflow
372	        if (longitude == 180.0D) {
373	            longitude = Math.nextDown(longitude);
374	        }
375	        return (int) Math.floor(longitude / LON_DECODE);
376	    }
377	
378	    /** returns the latitude value from the string based geohash */
379	    public static final double decodeLatitude(final String geohash) {
380	        return decodeLatitude(Geohash.mortonEncode(geohash));
381	    }
382	
383	    /** returns the latitude value from the string based geohash */
384	    public static final double decodeLongitude(final String geohash) {
385	        return decodeLongitude(Geohash.mortonEncode(geohash));
386	    }
387	
388	    /** decode longitude value from morton encoded geo point */
389	    public static double decodeLongitude(final long hash) {
390	        return unscaleLon(BitUtil.deinterleave(hash));
391	    }
392	
393	    /** decode latitude value from morton encoded geo point */
394	    public static double decodeLatitude(final long hash) {
395	        return unscaleLat(BitUtil.deinterleave(hash >>> 1));
396	    }
397	
398	    private static double unscaleLon(final long val) {
399	        return (val / LON_SCALE) - 180;
400	    }
401	
402	    private static double unscaleLat(final long val) {
403	        return (val / LAT_SCALE) - 90;
404	    }
405	}
